  // so most fortunes are white and the rarest few pink; the Grade and the fortunes' order keep tier
  const CTK = {}; [0.89, 0.09, 0.0175, 0.0025].forEach((g, t) => { const l = FORTUNES.filter(e => e[1] === t), s = l.reduce((a, e) => a + e[2], 0); for (const e of l) CTK[e[0]] = g * e[2] / s / e[3].length; });
