    const cs = COLS.slice(); for (let i = cs.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); const t = cs[i]; cs[i] = cs[j]; cs[j] = t; }
    const pods = cs.slice(0, 4);                  // NW, NE, SW, SE
