  // Fridge and Kitchen are look traits with exact chances: the model's weight, times its class's (the rare finishes' weight among
  // the finishes that model comes in, or the rest), shared evenly by the class's forms and by the five handle styles; and the
  // kitchen's weight times the hour's (late at night 38%)
  const tot = a => a.reduce((s, e) => s + e[1], 0), FRIDGE = {}, KITCHEN = {};
  for (const [m, wm] of MODELS) {
    const fs = finishesOf(m), t = tot(fs), rare = fs.filter(f => f[1] < 2).reduce((a, f) => a + f[1], 0);
    [[t - rare, FORMOF[m][0]], [rare, FORMOF[m][1]]].forEach(([w, names]) => { if (w > 0) for (const n of names) for (const h of HSTYLE) FRIDGE[m + ', ' + n.toLowerCase() + ', ' + h + ' handles'] = wm / tot(MODELS) * w / t / names.length / HSTYLE.length; });
  }
  for (const [k, wk] of KITCHENS) { KITCHEN[k + ', morning'] = wk / tot(KITCHENS) * 0.62; KITCHEN[k + ', late at night'] = wk / tot(KITCHENS) * 0.38; }
  const traits = {
    'Grade': { joint: 'g1', values: ProtoRolls.marginal(JOINT, 0) },
    'Also on the Door': { list: true },
    'The Word': { joint: 'g1', values: ProtoRolls.marginal(JOINT, 1) },
    'Pride of Place': { list: true },
    'Fridge': { look: true, values: FRIDGE },
    'Kitchen': { look: true, values: KITCHEN },
    'Rarest': { list: true },
  };
  // a cell names the word: natural draws the picks behind it until they spell it (above), so only the Grade is left to retries
  const fixOf = ([, word]) => ({ Word: word });
  // (deal, when the site deals one, goes to natural with the cell's word and stays in __pick)
  return { traits, natural, roll: (hash, deal) => ProtoRolls.byCell(hash, { natural, joint: JOINT, keys: ['Grade', 'The Word'], fixOf: cell => Object.assign(fixOf(cell), deal ? { deal: { card: deal.card, of: deal.of } } : {}) }) };
