    // what else is down there, and Letter Lock's padlock (1 in 50): rolls of their own
    const rrv = rnd();
    const down = fix.down || (rrv < 0.025 ? 'safe' : rrv < 0.053 ? 'magnet' : rrv < 0.163 ? 'eel' : rrv < 0.275 ? 'ring' : 'none');
    const lettered = rnd() < 1 / 50;
    // the haul: a falling count, full rarely
    const MAXN = 9;
    const full = rnd() < 0.04;
    let n;
    if (full) n = MAXN; else { const u = rnd(); n = u < 0.08 ? 2 : u < 0.86 ? 3 + Math.floor((u - 0.08) / 0.78 * 4) : 7 + (rnd() < 0.5 ? 1 : 0); }
    const finds = [];
    const used = {};
    for (let i = 0; i < n; i++) {
      let th; let guard = 0, named = null;
      if (rnd() < 1 / 800) { const L = LEGENDS[Math.floor(rnd() * LEGENDS.length)]; th = THINGS.find(q => q.n === L[0]); named = L[1]; }
      else do { th = wp(THINGS); guard++; } while (used[th.n] >= (th.tier >= 1 ? 1 : 2) && guard < 40);
      used[th.n] = (used[th.n] || 0) + 1;
      let st; do st = wp(STATES); while (st.ok && !st.ok(th));
      const o = named ? 1 : rnd(), origin = o < 0.3 ? ORIGINS[Math.floor(rnd() * ORIGINS.length)] : null;
      const stamp = !origin && th.tl && o < 0.62 ? STAMPS[Math.floor(rnd() * STAMPS.length)] : null;
      const ur = rnd();
      const up = ur < 0.05 && WORKS.has(th.n) ? 2 : ur < 0.17 ? 1 : 0;
      finds.push({ th, st, origin, stamp, named, up, paint: Math.floor(rnd() * 3) });
    }
    if (lettered) { const sp = finds[0]; sp.th = LETTERLOCK; sp.named = null; sp.origin = null; sp.stamp = null; sp.word = LL_WORDS[Math.floor(rnd() * LL_WORDS.length)]; sp.st = STATES[5]; }
    if (down === 'safe' || down === 'magnet') { const sp = finds[finds.length - 1]; sp.th = down === 'safe' ? SAFE : LOSTMAG; sp.st = down === 'safe' ? STATES[3] : STATES[5]; sp.origin = null; sp.stamp = null; sp.up = 0; sp.named = null; }
    const safeOpen = false;
    const tierOld = f => f.named ? 3 : f.th.tier;
    const tierOf = f => { const t = tierOld(f); return t >= 2 ? 3 : t === 1 ? (f.up && f.origin ? 3 : f.th === LOSTMAG || f.up || f.origin ? 2 : 1) : f.up === 2 ? 2 : f.up === 1 ? 1 : 0; };
    const name = f => {
      if (f.th === SAFE) return safeOpen ? "The Lock-Keeper's Safe (Wages Still In It)" : "The Lock-Keeper's Safe";
      if (f.th === LOSTMAG) return "Somebody Else's Magnet (Rope Snapped)";
      if (f.th === LETTERLOCK) return 'Letter Lock\'s Padlock (Still Set to ' + f.word + ')';
      let s = f.named ? f.named : f.st.n + ' ' + f.th.n + (f.origin ? ' ' + f.origin : '');
      if (f.stamp) s += ' (Stamped ' + f.stamp + ')';
      else if (f.up === 1) s += ' (Magnetised)'; else if (f.up === 2) s += ' (Still Works)';
      return s;
    };
    const keyHere = finds.some(f => f.th.n === 'Door Key' || f.th.n === 'Skeleton Key' || f.th.n === 'Bunch of Keys'), lockHere = finds.some(f => f.th.n === 'Padlock' || f.th.n === 'Bike Lock');
    const pairs = Object.keys(used).filter(k => used[k] >= 2);
    const setName = keyHere && lockHere ? 'Lock and Key' : pairs.length ? 'Pair of ' + pairs[0] + (pairs[0].endsWith('s') ? '' : 's') : 'None';
    const score = finds.reduce((s, f) => s + [1, 2.5, 5, 9][tierOld(f)] + f.up * 2 + (f.origin ? 0.5 : 0), 0) + (setName === 'Lock and Key' ? 5 : setName !== 'None' ? 2 : 0) + (full ? 8 : 0);
