    return { rows: rows.filter(t => !t[0].startsWith('__')).concat(rows.filter(t => t[0].startsWith('__'))), LT, WT, ST, place, housed: !!HOUSED[place], MG, kg, down, lettered, full, n, finds, bestI: finds.indexOf(best), SAFE, LOSTMAG, LETTERLOCK };
